DROP TABLE IF EXISTS node; DROP TABLE IF EXISTS evidence; DROP TABLE IF EXISTS lines; DROP TABLE IF EXISTS alias;
CREATE TABLE node (node_id INT, lvl INT, p TEXT, a TEXT, e TEXT, f TEXT, fn TEXT, bu TEXT, cc TEXT, own TEXT, pl TEXT, cust TEXT);
CREATE TABLE evidence (kind TEXT, k TEXT, node_id INT);
CREATE TABLE alias (hier TEXT, lvl INT, v TEXT, code TEXT);
CREATE TABLE lines (line_id INT, resource_id TEXT, rg TEXT, account TEXT, region TEXT, lz TEXT, p TEXT, a TEXT, e TEXT, f TEXT, fn TEXT, bu_tag TEXT, cc_tag TEXT, own_tag TEXT, pl_tag TEXT, cust_tag TEXT);
